# Get non-empty, non-comment lines
lines = [line.strip() for line in student_code.split('\n') if line.strip() and not line.strip().startswith('#')]
full_code = '\n'.join(lines)
full_upper = full_code.upper()
# Remove all whitespace for pattern matching
full_compact = ''.join(full_upper.split())

# Task 2: Check CREATE TABLE
if 'CREATETABLEIFNOTEXISTSPRODUCTS' not in full_compact:
    raise AssertionError('Task 2: Missing CREATE TABLE IF NOT EXISTS for products')

# Task 3: Check executemany
if 'executemany' not in full_code:
    raise AssertionError('Task 3: Should use executemany()')
if 'Inserted 6 sample products' not in full_code:
    raise AssertionError('Task 3: Should print "Inserted 6 sample products."')

# Task 4: Check SELECT all products (using compact form)
if 'SELECT' not in full_upper or 'FROMPRODUCTS' not in full_compact:
    raise AssertionError('Task 4: Should SELECT FROM products')

# Task 5: Check SELECT electronics
if 'WHERECATEGORY=?' not in full_compact and 'WHERECATEGORY = ?' not in full_upper:
    raise AssertionError('Task 5: Should filter by category')
if not any("('Electronics',)" in line or '("Electronics",)' in line for line in lines):
    raise AssertionError("Task 5: Should use ('Electronics',) as parameter")

# Task 6: Check SELECT low stock
if 'WHERESTOCK<?' not in full_compact and 'WHERE STOCK < ?' not in full_upper:
    raise AssertionError('Task 6: Should filter by stock < ?')

# Task 7: Check SUM
if 'SUM(PRICE*STOCK)' not in full_compact:
    raise AssertionError('Task 7: Should use SUM(price * stock)')

# Task 8: Check UPDATE laptop
if 'UPDATEPRODUCTSSETPRICE' not in full_compact:
    raise AssertionError('Task 8: Should UPDATE the price')
if 'Updated Laptop price' not in full_code:
    raise AssertionError('Task 8: Should print laptop update confirmation')

# Task 9: Check UPDATE notebook stock
if 'STOCK=STOCK+?' not in full_compact:
    raise AssertionError('Task 9: Should use stock = stock + ?')
if 'Restocked Notebook' not in full_code:
    raise AssertionError('Task 9: Should print notebook restock confirmation')

# Task 10: Check DELETE
if 'DELETEFROMPRODUCTS' not in full_compact:
    raise AssertionError('Task 10: Should DELETE FROM products')
if 'Deleted Pen' not in full_code:
    raise AssertionError('Task 10: Should print pen deletion confirmation')

# Check commits (at least 4)
commit_count = full_code.count('conn.commit()')
if commit_count < 4:
    raise AssertionError(f'Should have at least 4 commits, found {commit_count}')

print('TEST_PASSED')
